// Push, retrying transient network failures on the same 0/2/4/8/16s back-off
// 3-prepare.sh used. A push that fails once here would otherwise throw away a
// scaffold, an offline-suite run and a paid page fetch.
function push(branch, waitMs = [2000, 4000, 8000, 16000]) {
  const remote = `https://x-access-token:${TOKEN}@github.com/${REPO}.git`;
  for (let attempt = 0; ; attempt += 1) {
    try {
      git('push', '--force', remote, `HEAD:refs/heads/${branch}`);
      return;
    } catch (e) {
      if (attempt >= waitMs.length) throw e;
      execFileSync(process.execPath, ['-e', `setTimeout(()=>{}, ${waitMs[attempt]})`]);
    }
  }
}

// The draft PR the agent continues on. Its number reaches the agent through the dispatch
// issue (the handoff at the foot of main); the `claude/extractor/` prefix is this task's
// own bookkeeping for reclaiming stale requests. DRAFT because the extractor is not
// written yet; the agent marks it ready when the postconditions pass.
async function openDraftPr(decision, base, issueNumber) {
  const body = [
    `Closes #${issueNumber}`,
    '',
    `Automated extractor pipeline for \`${decision.host}\` (${decision.mode === 'supported' ? 'adds an integration case to an existing source' : 'new source'}).`,
    '',
    'Scaffold, the recorded page, and a green offline baseline were prepared deterministically by the',
    '`gcec/create-extractor` task\'s preprocessing. The extractor implementation and the case values are',
    'the agent stage\'s work; this PR is a draft until they land and its postconditions pass.',
  ].join('\n');
  const { status, json } = await gh(`/repos/${REPO}/pulls`, {
    method: 'POST',
    body: { head: decision.branch, base, title: prTitle(decision.mode, decision.host, decision.sourceBase), body, draft: true },
  });
  if (status >= 300) throw new Error(`could not open the draft PR: ${status} ${JSON.stringify(json?.errors ?? json?.message ?? '')}`);
  return json.number;
}

// Record every case whose `.url` is committed but whose `.html` is not, and deliver
// them on the sweep's own branch/PR (separate from any extractor PR — a missing page
// is a repo-maintenance fix, not part of implementing a site). Returns the number
// recorded. A page that will not record does NOT sink the run: the others still
// land and the failure is reported in the PR body.
async function sweepPendingPages(key, base, budgetMs) {
  const dir = join(ROOT, DATA_DIR);
=== scaffold.js ===
// Deterministic scaffolding for the create-extractor task's preprocessing stage
// (prepare.mjs), merged from what used to be three files (scaffold-source /
// scaffold-case / add-supported-domain). Everything here is derivable from the
// event URL + mode before the agent runs; the agent's only job is to fill
// extract() + the case against the real recorded page.
//
//   node scaffold.js <mode> <caseName> <host> [event-url]
//     supported : write ONLY the placeholder case for the existing source
//     new       : write the source stub (matches() filled) + the placeholder case,
//                 and register <host> in supportedDomains. (prepare.mjs then runs
//                 `npm run index`.)
//
// Refuses to overwrite an existing source or case (a real one must never be
// clobbered by a re-run). Pure functions are exported for the unit tests; the CLI
// is just file I/O around them.
"use strict";

const fs = require("node:fs");
const path = require("node:path");
const { hostname, slugFor, matchesRegexFor, namesFor } = require("./extractor-naming");
const { ROOT } = require("./repo-root");
const sourcePath = (slug) => path.join(ROOT, "extension", "event-extractors", "custom", `${slug}.js`);
const casePath = (name) => path.join(ROOT, "dev", "requirements", "extractor", "expected", `${name}.json`);
const LISTS_FILE = path.join(ROOT, "extension", "host-lists.json");

// Pure: the source-file text for a URL. The header + matches() are complete; the
// extract() body is a starting point the agent refines against the cached page.
function sourceStub(url) {
  const host = hostname(url);
  const slug = slugFor(url);
  const { caseName } = namesFor(url);
  const matchesRegex = matchesRegexFor(url);
  return `// ${host} event pages: ${url}
//
// TODO(agent): document the page's structure and where each field is read from,
// mirroring event-extractors/custom/meetup.js. The real page is cached at
// dev/requirements/extractor/data/server-fetched/${caseName}.html.
//
// This source is a layer of OVERRIDES over the core generic extractor
// (generic-extractor.js), which has already read the page's own
// schema.org JSON-LD, Open Graph tags, microdata and visible dates. State ONLY
// the fields it gets wrong — anything you leave out comes from that base. If it
// turns out to get everything right, just delete this file — the host is already
// registered in supportedDomains, so the site stays fully supported without it.
(() => {
  const { text, firstText, blockText, normalizeDateValue } = GCal;

  GCal.sources.push({
    name: "${slug}",
    matches: (host) => ${matchesRegex}.test(host),
    extract() {
      // TODO(agent): refine these selectors against dev/requirements/extractor/data/server-fetched/${caseName}.html,
      // dropping any the generic base already gets right and adding location /
      // description / ctz as the page needs them.
      return {
        title: text("h1"),
        start: (() => {
          const el = document.querySelector("time[datetime]");
          return el ? normalizeDateValue(el.getAttribute("datetime")) : "";
        })(),
      };
    },
  });
})();
`;
}

// Pure: the placeholder case object for a host. Empty `events` means "not filled
// yet" — the routine's quality floor treats a still-empty case as a bail.
function caseStub(host) {
  return {
    description: `${host}: TODO(agent) — one line on what this case tests`,
    expected: { events: [] },
  };
}

// Pure: return `list` with `host` present, sorted and de-duplicated.
function withDomain(list, host) {
  return [...new Set([...(list || []), host])].sort();
}

module.exports = { sourceStub, caseStub, withDomain };

function writeNew(file, contents, label) {
  if (fs.existsSync(file)) {
    console.error(`scaffold: ${file} already exists — refusing to overwrite`);
    process.exit(1);
  }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, contents);
  console.log(`scaffold: wrote ${label}`);
}

if (require.main === module) {
  const [mode, caseName, host = "", url = ""] = process.argv.slice(2);
  if (!mode || !caseName) {
    console.error("scaffold: usage: scaffold.js <mode> <caseName> <host> [event-url]");
    process.exit(1);
  }

  // The placeholder case — both modes.
  writeNew(casePath(caseName), JSON.stringify(caseStub(host), null, 2) + "\n",
    `dev/requirements/extractor/expected/${caseName}.json`);

  if (mode === "new") {
    const slug = slugFor(url);
    if (!url || !slug) {
      console.error(`scaffold: new mode needs a usable event URL (got ${JSON.stringify(url)})`);
      process.exit(1);
    }
    writeNew(sourcePath(slug), sourceStub(url), `extension/event-extractors/custom/${slug}.js`);

    const lists = JSON.parse(fs.readFileSync(LISTS_FILE, "utf8"));
    lists.supportedDomains = withDomain(lists.supportedDomains, host);
    fs.writeFileSync(LISTS_FILE, JSON.stringify(lists, null, 2) + "\n");
    console.log(`scaffold: "${host}" registered in supportedDomains (${lists.supportedDomains.length} total)`);
  }
}

