  'no-open-pr-touching': {
    signals: ['prs'],
    takesArg: true,
    argName: 'path-prefix',
    holds(s, { arg }) {
      const pending = openPrs(s).find((p) => Array.isArray(p.changedPaths) && p.changedPaths.some((f) => f.startsWith(arg)));
