mkdir -p .scratch && cat > .scratch/inline.mjs <<'EOF'
const M = '../.claudinite/shared/packs/claudinite-tasks/merge-policy.mjs';
const { policyVerdict, normalizePolicy } = await import(M);

const entry = (file) => ({ file, before: null, after: 'x' });
const try_ = (label, policy, files) => {
  const norm = normalizePolicy(policy);
  const v = policyVerdict({ policy, entries: files.map(entry) });
  console.log(`${label}\n   parses: ${norm.kind}${norm.reason ? ' — ' + norm.reason : ''}`);
  console.log(`   mergeable: ${v.mergeable}${v.mergeable ? '' : ' — ' + v.why}\n`);
};

// Can an inline term name a single FILE? Both rules need to.
try_('under: pointing at a file', ['under:extension/host-lists.json'], ['extension/host-lists.json']);

// Is there any inline regex/glob form at all?
try_('an inline regex', ['/^extension/host-lists\\.json$/'], ['extension/host-lists.json']);
try_('an inline glob', ['extension/*.json'], ['extension/host-lists.json']);

// The only inline shape that DOES cover those files — and what else it lets in.
try_('under:extension, on the two files the rule needs',
  ['under:extension'], ['extension/host-lists.json', 'extension/event-extractors/load-order.generated.json']);
try_('under:extension, on files create-extractor must NOT touch',
  ['under:extension'], ['extension/event-extractors/helpers/dates.js', 'extension/events-popup/popup.js']);
EOF
node .scratch/inline.mjs

